Decorators are functions that take another function as an argument and return a new function with enhanced behavior. They use the `@` syntax for a cleaner way to apply them.

### Basic Concept
```python
def my_decorator(func):
    def wrapper():
        print("Something before the function")
        func()
        print("Something after the function")
    return wrapper

@my_decorator
def say_hello():
    print("Hello!")
```

### Simple Decorator
```python
def timer(func):
    def wrapper(*args, **kwargs):
        import time
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"{func.__name__} took {end - start:.4f} seconds")
        return result
    return wrapper

@timer
def slow_function():
    import time
    time.sleep(1)
    return "Done!"
```

### Decorator with Arguments
```python
def repeat(times):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for _ in range(times):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

@repeat(3)
def greet(name):
    print(f"Hello, {name}!")
```

### Decorator Factory
```python
def validate_input(validator_func):
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Validate arguments
            if not validator_func(*args, **kwargs):
                raise ValueError("Invalid input")
            return func(*args, **kwargs)
        return wrapper
    return decorator

def is_positive(x):
    return x > 0

@validate_input(is_positive)
def square_root(x):
    return x ** 0.5
```

### Function as Class Decorator
```python
def singleton(cls):
    instances = {}
    def get_instance(*args, **kwargs):
        if cls not in instances:
            instances[cls] = cls(*args, **kwargs)
        return instances[cls]
    return get_instance

@singleton
class Database:
    def __init__(self):
        print("Creating database connection...")
```

### Class as Decorator
```python
class Timer:
    def __init__(self, func):
        self.func = func
        self.count = 0

    def __call__(self, *args, **kwargs):
        self.count += 1
        print(f"Function called {self.count} times")
        return self.func(*args, **kwargs)

@Timer
def greet(name):
    print(f"Hello, {name}!")
```

### @property
```python
class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def radius(self):
        return self._radius

    @radius.setter
    def radius(self, value):
        if value < 0:
            raise ValueError("Radius cannot be negative")
        self._radius = value

    @property
    def area(self):
        return 3.14159 * self._radius ** 2
```

### @staticmethod and @classmethod
```python
class Date:
    def __init__(self, year, month, day):
        self.year = year
        self.month = month
        self.day = day

    @staticmethod
    def is_valid_date(year, month, day):
        return 1 <= month <= 12 and 1 <= day <= 31

    @classmethod
    def from_string(cls, date_string):
        year, month, day = map(int, date_string.split('-'))
        return cls(year, month, day)
```

### @functools.wraps
```python
from functools import wraps

def my_decorator(func):
    @wraps(func)  # Preserves function metadata
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper
```

### Caching/Memoization
```python
def memoize(func):
    cache = {}

    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]

    return wrapper

@memoize
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)
```

### Retry Logic
```python
def retry(max_attempts=3, delay=1):
    def decorator(func):
        def wrapper(*args, **kwargs):
            import time
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt == max_attempts - 1:
                        raise e
                    time.sleep(delay)
            return None
        return wrapper
    return decorator

@retry(max_attempts=3, delay=2)
def unreliable_function():
    import random
    if random.random() < 0.7:
        raise Exception("Random failure")
    return "Success!"
```

### Logging
```python
def log_function(func):
    import logging
    logging.basicConfig(level=logging.INFO)

    def wrapper(*args, **kwargs):
        logging.info(f"Calling {func.__name__} with args={args}, kwargs={kwargs}")
        result = func(*args, **kwargs)
        logging.info(f"{func.__name__} returned {result}")
        return result

    return wrapper

@log_function
def add(a, b):
    return a + b
```

### Validation
```python
def validate_types(*types):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for arg, expected_type in zip(args, types):
                if not isinstance(arg, expected_type):
                    raise TypeError(f"Expected {expected_type}, got {type(arg)}")
            return func(*args, **kwargs)
        return wrapper
    return decorator

@validate_types(int, int)
def multiply(a, b):
    return a * b
```

### Decorator Chaining
```python
def bold(func):
    def wrapper():
        return f"<b>{func()}</b>"
    return wrapper

def italic(func):
    def wrapper():
        return f"<i>{func()}</i>"
    return wrapper

@bold
@italic
def hello():
    return "Hello, World!"
```

### Decorators with State
```python
def counter(func):
    def wrapper(*args, **kwargs):
        wrapper.count += 1
        print(f"Function called {wrapper.count} times")
        return func(*args, **kwargs)
    wrapper.count = 0
    return wrapper

@counter
def greet(name):
    print(f"Hello, {name}!")
```

### Context Manager Decorator
```python
def with_context(context_manager):
    def decorator(func):
        def wrapper(*args, **kwargs):
            with context_manager:
                return func(*args, **kwargs)
        return wrapper
    return decorator

@with_context(open('output.txt', 'w'))
def write_data():
    print("Writing data...")
```

### 1. Preserve Function Metadata
```python
from functools import wraps

def my_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper
```

### 2. Handle Arguments Properly
```python
def my_decorator(func):
    def wrapper(*args, **kwargs):
        # Process arguments
        return func(*args, **kwargs)
    return wrapper
```

### 3. Use Meaningful Names
```python
def validate_input(func):
    def validate_wrapper(*args, **kwargs):
        # Validation logic
        return func(*args, **kwargs)
    return validate_wrapper
```

### 4. Document Your Decorators
```python
def retry(max_attempts=3):
    """
    Retry decorator that attempts to call a function multiple times.

    Args:
        max_attempts (int): Maximum number of attempts

    Returns:
        function: Decorated function
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Retry logic
            pass
        return wrapper
    return decorator
```
